body#layout{width:90%;position:relative;background-color:#f9f9f9;padding:95px 5px 0;margin:0}
body#layout:before{content: 'LUVIET-2024'; position: absolute; top: 0; left: 5px; right: 5px; height: 60px; font-family: Roboto,sans-serif; font-size: 23px; color: #fff; line-height: 60px; text-align: center; background: #000; margin: 0px 4px 0 5px;}
body#layout:after{content: 'Design by LuViet WebBlog'; display: block; font-family: Roboto,sans-serif; font-size: 14px; color: #fff; line-height: 1; text-align: center; visibility: visible; padding: 20px 0; background: #000; margin: 0px 4px 0 5px;}
body#layout div.layout-title {white-space: nowrap;}
body#layout div.section{display:block;background-color:#f1f1f1!important;margin:0 5px 10px!important;padding:16px 16px 18px!important;border-color:#e5e5e5}
body#layout .no-items.section{display:block}
body#layout .section h4{font-size:14px;color:#1f2024;text-transform:uppercase;margin:0}
body#layout .section h4:after{text-transform:initial;color:#656565;font-weight:400}
body#layout .add_widget a{color:#3c97ef!important}
body#layout .widget-wrap3{overflow:hidden}
body#layout .widget-content{width:auto;max-width:none;max-height:none;margin:0;border:1px solid #e5e5e5;border-left:0}
body#layout .locked-widget .widget-content{border-left:1px solid #3c97ef}
body#layout .locked-widget .widget-content:hover{border-left-color:#00b140}
body#layout .widget .widget-content a.editlink{border-radius:2px}
body#layout .visibility .editlink{background:#3c97ef url(https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEjlmrXd6t_6XIebP-T4sM1r9eS0KSyDq_CRm0i_Fig3M8Rx78iSk7UNl-AF6JmewFvn8JPTZP6Ozza-l4syXUNSD_s8M3T2_p5Vrr72zFbEZG5bPrGH_vu-XKuaYBsiQJ1xu_f-BNEaGkA/s18-c/mode_edit_w600_24dp.png) no-repeat center!important}
body#layout .visibility .editlink:hover{background-color:#00b140!important}
body#layout div.layout-widget-description{display:none}
body#layout {width: 95%;}
body#layout ul{list-style-type:none;list-style:none}
body#layout ul li{list-style-type:none;list-style:none}
body#layout .header{float:left;width:100%;clear:both}
body#layout .header .col-md-6{float:left;width:50%}
body#layout .header .header-main .col-100-h{float:left;width:50%}
body#layout .header .header-main .col-lg-4{float:left;width:50%}
body#layout .header .header-main .items-cart-inner{display:none}
body#layout .footer-container{float:left;width:100%;clear:both}
body#layout .awe-section-1 {float:left;width:100%;clear:both}
body#layout .awe-section-2 {float:left;width:100%;clear:both}
body#layout .awe-section-2 .col-lg-4{float:left;width:33.3333%}
body#layout .awe-section-3 {float:left;width:100%;clear:both}
body#layout .awe-section-4 {float:left;width:100%;clear:both}
body#layout .awe-section-5 {float:left;width:100%;clear:both}
body#layout .awe-section-6 {float:left;width:100%;clear:both}
body#layout .awe-section-7 {float:left;width:100%;clear:both}
body#layout .awe-section-8 {float:left;width:100%;clear:both}
body#layout .awe-section-9 {float:left;width:100%;clear:both}
body#layout .awe-section-10 {float:left;width:100%;clear:both}
body#layout .awe-section-11 {float:left;width:100%;clear:both}
body#layout .product-fpt-with-stick-nav{float:left;width:100%;clear:both;padding-top: 10px;background: #f57c00;margin-bottom: 10px;}
body#layout .ant-sidebar{float:left;width:100%;clear:both}
body#layout .ant-sidebar .co-50{float:left;width:47.5%}
body#layout #id-collections-top-sal{float:left;width:95%;clear:both}
body#layout #pagesearch{background: #3c97ef; padding: 9px 0px 0px 0px; float: left; width: 100%;}
body#layout #id-category h4:after{content:' - Chỉ  hiện trong danh mục'}
body#layout #id-aside-filter h4:after{content:' - Chỉ  hiện trong danh mục'}
body#layout #id-collections-top-sal h4:after{content:' - Chỉ  hiện trong danh mục'}
body#layout #id-menu-mobile h4:after{content:' - Menu 2 cấp sử  dụng dấu _ để  tạo menu con'}
body#layout #id-logo h4:after{content:' - Chọn và  Upload logo'}
body#layout #id-social h4:after{content:' - Mạng xã  hội mặc định 4 icon'} 
body#layout #id-links h4:after{content:' - Liên kết tùy chỉnh kèm icon Font Awesome'} 
body#layout #id-support h4:after{content:' - Số  điện thoại'} 
body#layout #id-nav h4:after{content:' - Chỉnh sửa menu trong HTML'}
body#layout #id-home-slider h4:after{content:' - Slider ảnh'}
body#layout #id-banner-1 h4:after{content:' - Chỉnh sửa nội dung'}
body#layout #id-banner-2 h4:after{content:' - Chỉnh sửa nội dung'}
body#layout #id-banner-3 h4:after{content:' - Chỉnh sửa nội dung'}
body#layout #id-products h4:after{content:' - Sản phẩm Slider - Tiêu đề  và  Nhãn'}
body#layout #id-products .add_widget{display:none}
body#layout #id-about-us h4:after{content:' - Chỉnh sửa nội dung'}
body#layout #id-product h4:after{content:' - Tiêu đề  và  Nhãn'}
body#layout #id-producta h4:after{content:' - Tiêu đề  và  Nhãn'}
body#layout #id-policy h4:after{content:' -Chính sách bán hàng'}
body#layout #id-categories h4:after{content:' - Chỉnh sửa nội dung'}
body#layout #id-news h4:after{content:' - Tin tức Blog'}
body#layout #sidebar-right{float:left;width:95%;clear:both}
body#layout #content{float:left;width:95%;clear:both}
body#layout #content .add_widget{display:none}
body#layout #chamsoccay h4:after{content:' - Chỉ  hiển thị  khi xem sản phẩm'}
body#layout #sidebar-right h4:after{content:' - Chỉ  hiển thị  khi xem sản phẩm'}
body#layout #content h4:after{content:' - Main blog'}
body#layout .col-md-4 {width:25%; float:left;}
body#layout .footer-bottom{float:left;width:100%;clear:right;}
body#layout #addthis-modalContact{display:none}





