.awe-section-3 { min-height: 392.67px; height: auto; overflow: hidden; }
.awe-section-1 { min-height: 431.63px; height: auto; overflow: hidden; }
.awe-section-2{ min-height: 285px; height: 285px; overflow: hidden; }
