  jQuery(document).ready(function(e) {
    var n = localStorage.getItem("simpleCart_items"),
      r = "",
      a = 0;
    if (n) {
      try {
        var items = e.parseJSON(n);
        if (items) {
          e.each(items, function(e, n) {
            var t = "+ Order #: " + (n.name || "Sản phẩm") + " ( " + String(n.price).replace(/(.)(?=(\d{3})+$)/g, "$1,") + " x " + n.quantity + " = " + String(n.price * n.quantity).replace(/(.)(?=(\d{3})+$)/g, "$1,") + " )\n";
            r += t;
            a += (n.price * n.quantity);
          });
          r += "- Phí giao hàng: Giao hàng Free qua Zalo/Email \n";
          r += "- VAT (0%): " + String(0 * a).replace(/(.)(?=(\d{3})+$)/g, "$1,") + " đ\n";
          var t = String(a + 0 * a + 0).replace(/(.)(?=(\d{3})+$)/g, "$1,");
          r += "- Tổng thanh toán: " + t + " đ";
          e("#layidthongtinsanpham").val(r);
        }
      } catch(err) {
        console.error("Lỗi đọc giỏ hàng:", err);
      }
    }
  });
  $(document).ready(function() {
    $("form").submit(function() {
      $("#order").toggle(), $(".hidden-message").show();
      $("iframe#hidden_iframe").on("load", function() {
        if(typeof simpleCart !== 'undefined') simpleCart.empty();
      });
    });
  });
  //





  $(document).ready(function() {
    $("form").submit(function() {
      $(".alert-success").removeClass('hidden');
      setTimeout(function() {
        $(".alert-success").addClass('hidden');
              document.getElementById("contact").reset();
      }, 4000);
    });
  });



