$(document).ready(function(){
  // DIEU HUONG TAT CA NUT MUA / TU VAN VE ZALO OA
  $(document).on("click", ".btn-zalo-direct, .item_add, .btn-buy-now-click, .btn_buy, .cvgio, .chovaogio, .btn-cart", function(e){
    // Neu la nut Fanpage thi bo qua de link fanpage chay
    if ($(this).hasClass("btn-fanpage-direct") || $(this).closest(".btn-fanpage-direct").length > 0) {
      return;
    }
    e.preventDefault();
    e.stopPropagation();

    var $item = $(this).closest(".simpleCart_shelfItem, .ant-single-product, .details-product, .productAnchor_horizonalNav, article");
    var productName = $(this).attr("data-title") || 
                      $item.find(".item_name").text().trim() || 
                      $item.find(".product-title a").text().trim() || 
                      $item.find("h1.title-head").text().trim() || 
                      $item.find("h1.title_name").text().trim() || 
                      $("h1.title-head").text().trim() || 
                      $("h1.title_name").text().trim() || 
                      document.title.split("-")[0].trim() || 
                      "sản phẩm";
    var productPrice = $item.find(".item_price").text().trim() || $(".product_info_price_value-final").text().trim() || "";
    var currentUrl = $(this).attr("data-url") || window.location.href;

    var message = "Chào shop, tôi muốn được tư vấn mẫu: " + productName + (productPrice ? (" (Giá: " + productPrice + ")") : "") + "\nLink xem mẫu: " + currentUrl;
    var zaloLink = "https://zalo.me/1501073926693571291?text=" + encodeURIComponent(message);
    window.open(zaloLink, "_blank");
  });

  // DIEU HUONG NUT FANPAGE
  $(document).on("click", ".btn-fanpage-direct", function(e){
    e.preventDefault();
    var fbLink = "https://www.facebook.com/webluviet/";
    window.open(fbLink, "_blank");
  });
});
