document.addEventListener("DOMContentLoaded", function () {

    // =========================
    // DANH SÁCH POPUP (THÊM BAO NHIÊU CŨNG ĐƯỢC)
    // =========================
    const popups = [
        {
            title: "Mẫu Website Giá Rẻ",
            desc: "Full Hướng Dẫn Cài Đặt Từ A-Z.",
            image: "https://via.placeholder.com/400x250?text=Landing+Page",
            link: "https://www.luviet.com/search/label/website-wordpress",
            id: "website"
        },
        {
            title: "Khóa Học Thiết Kế Landing Page Bán Hàng",
            desc: "Tự xây dựng hệ thống Landing Page bán hàng tự động.",
            image: "https://content.pancake.vn/1/s920x920/fwebp80/66/31/fe/32/91364f1f8ebdd4d2974302e7529ba282707e2e0016405a96909fb095-w:1080-h:1080-l:435938-t:image/png.png",
            link: "https://thuan.luviet.com/he-thong-trang-ban-hang",
            id: "khóa học"
        },

    ];

    const popup = document.getElementById("dailyPopup");
    const lastShown = localStorage.getItem("popupLastShown");
    const now = new Date().getTime();
    const oneDay = 24 * 60 * 60 * 1000;

    if (!lastShown || now - lastShown > oneDay) {

        // RANDOM POPUP
        const randomPopup = popups[Math.floor(Math.random() * popups.length)];

        document.getElementById("popupTitle").innerText = randomPopup.title;
        document.getElementById("popupDesc").innerText = randomPopup.desc;
        document.getElementById("popupImage").src = randomPopup.image;
        document.getElementById("popupButton").href = randomPopup.link;

        popup.style.display = "flex";
        localStorage.setItem("popupLastShown", now);

        // TRACK GA4 VIEW
        if (typeof gtag === "function") {
            gtag('event', 'popup_view', {
                popup_id: randomPopup.id,
                popup_title: randomPopup.title
            });
        }

        // TRACK CLICK
        document.getElementById("popupButton").addEventListener("click", function(){
            if (typeof gtag === "function") {
                gtag('event', 'popup_click', {
                    popup_id: randomPopup.id,
                    popup_title: randomPopup.title
                });
            }
        });

        // Lưu ID để track khi close
        popup.setAttribute("data-popup-id", randomPopup.id);
        popup.setAttribute("data-popup-title", randomPopup.title);
    }
});

function closePopup(){
    const popup = document.getElementById("dailyPopup");
    const popupId = popup.getAttribute("data-popup-id");
    const popupTitle = popup.getAttribute("data-popup-title");

    popup.style.display = "none";

    if (typeof gtag === "function") {
        gtag('event', 'popup_close', {
            popup_id: popupId,
            popup_title: popupTitle
        });
    }
}

